// Single import point for contract types. Contracts come only from the generated file
// (never hand-edit src/contracts/generated.ts); this module re-exports them and adds the
// UI-only shapes of the static demo files.
import type {
  Equipment,
  Finding,
  Material,
  Opportunity,
  Project,
  ProjectBundle,
  PurchaseRequisition,
  RunEvent,
  RunRecord,
  TopologyOption,
  WhatIfResult,
} from '@/contracts/generated'

export type {
  Approval,
  Citation,
  ClauseRef,
  Connection,
  CoolingNode,
  CrmOverlay,
  DesignBrief,
  DesignModel,
  Equipment,
  Finding,
  Geometry,
  LedgerEntry,
  Material,
  OpenQuestion,
  Opportunity,
  Pipe,
  PlanStep,
  Point3,
  PRLine,
  Project,
  ProjectBundle,
  PurchaseRequisition,
  Rack,
  Requirement,
  Revision,
  RunEvent,
  RunRecord,
  StepRecord,
  TopologyOption,
  WhatIfResult,
} from '@/contracts/generated'

export type ProjectState = Project['state']
export type AssetPack = Project['asset_pack']
export type FindingStatus = Finding['status']
export type AgentName = RunEvent['agent']
export type EventKind = RunEvent['kind']
export type Phase = RunEvent['phase']
export type EquipmentKind = Equipment['kind']
export type TopologyId = TopologyOption['id']
export type WhatIfParam = WhatIfResult['param']
export type Autonomy = RunRecord['autonomy']

/** A ProjectBundle with every optional collection filled in (see normalizeBundle). */
export type Bundle = Required<ProjectBundle>

export function normalizeBundle(b: ProjectBundle): Bundle {
  return {
    project: b.project,
    brief: b.brief ?? null,
    runs: b.runs ?? [],
    steps: b.steps ?? [],
    events: [...(b.events ?? [])].sort((x, y) => x.seq - y.seq),
    revisions: [...(b.revisions ?? [])].sort((x, y) => x.created_at - y.created_at),
    findings: b.findings ?? {},
    approvals: b.approvals ?? [],
    prs: b.prs ?? [],
    crm: b.crm ?? null,
    what_ifs: b.what_ifs ?? [],
  }
}

/** Static demo world (`public/demo/world.json`, generated by WS4). */
export interface WorldPerson {
  id: string
  name: string
  role: string
  initials?: string
}
export interface WorldActivity {
  id: string
  ts: number // unix seconds
  actor: string
  project_id?: string | null
  text: string
}
export interface World {
  org: { name: string; tagline?: string }
  people: WorldPerson[]
  projects: Project[]
  activity: WorldActivity[]
}

/** Static integrations snapshot (`public/demo/integrations.json`, generated by WS4). */
export interface DocumentRecord {
  id: string
  project_id: string
  name: string
  kind: string // "tender" | "drawing" | "calc_report" | "boq" | ...
  url: string // public URL (e.g. /demo/docs/tender-hall-a.pdf)
  updated_at: number
}
export interface NotificationRecord {
  id: string
  ts: number
  kind: string // "approval" | "finding" | ...
  title: string
  body?: string
  project_id?: string | null
}
export interface IntegrationsSnapshot {
  synced_at?: number
  erp: { materials: Material[]; prs: PurchaseRequisition[] }
  crm: { opportunities: Opportunity[] }
  documents: DocumentRecord[]
  notifications: NotificationRecord[]
}

/** Asset-pack result dict (interfaces doc: evaluate_grid/evaluate_solar; `POST /api/asset/{pack}`). */
export interface AssetResult {
  options: Record<string, unknown>[]
  recommended: string
  findings: Finding[]
  geometry: Record<string, unknown>
  sld?: { nodes: { id: string; kind: string; label: string }[]; edges: { src: string; dst: string; label?: string }[] }
  /** The Asset agent's pick (WS2 ruling R33); `source: 'engine'` when the agent fell back to `recommended`. */
  choice?: { option: string; reason: string; source: 'agent' | 'engine' }
}

/** Bids inbox (spec §20): `public/demo/inbox.json` (WS4 I-1) and `GET /api/inbox` (WS2 I-2). Hand-typed like `World`. */
export type AttachmentKind = 'tender' | 'drawing' | 'addendum' | 'boq' | 'brochure' | 'other'
export type InboxFieldKey = 'client' | 'site' | 'asset_type' | 'mw' | 'redundancy' | 'bid_due' | 'lead_time_weeks'
export type Verification = 'verified' | 'unverified_scan' | 'unverified'
export type Verdict = 'pursue' | 'clarify' | 'decline'
export interface InboxAttachment {
  id: string
  name: string
  url: string // /demo/docs/{file} or /demo/inbox/{file}
  source: string
  content_type: string
}
export interface AttachmentTriage {
  attachment_id: string
  name: string
  kind: AttachmentKind
  scanned: boolean
}
export interface ExtractedField {
  key: InboxFieldKey
  label: string
  value: string | number | null // null when withheld (unverified)
  unit: string | null
  display: string // formatted by WS2 from the verified value
  source: string
  source_label: string
  page: number | null
  quote: string // the verified verbatim quote; "" when unverified
  verification: Verification
  bbox: number[] | null
}
export interface CrmLink {
  account: string | null
  opportunity_id: string | null
  opportunity_name: string | null
  stage: string | null
  proposed: boolean
  proposed_name: string | null
}
export interface FitReason {
  rule: 'asset_pack' | 'mw_range' | 'region' | 'deadline' | 'supply' | 'not_a_bid'
  status: FindingStatus
  text: string
}
export interface SupplyCheck {
  status: 'ok' | 'swap' | 'risk' | 'not_assessed'
  text: string
  topology: string | null
  mw: number | null
  lead_limit_weeks: number | null
  material_id: string | null
  lead_time_weeks: number | null
  stock: number | null
  swap_to: string | null
  swap_stock: number | null
}
export interface FitResult {
  verdict: Verdict | null // null: not a bid
  headline: string
  reasons: FitReason[]
  supply: SupplyCheck | null
}
export interface TriageResult {
  email_id: string
  is_bid: boolean
  summary: string
  attachments: AttachmentTriage[]
  fields: ExtractedField[]
  crm: CrmLink
  fit: FitResult
  quotes_verified: number
  quotes_total: number
  source: 'live' | 'precomputed'
  model: string
  triaged_at: number
  tokens_in: number
  tokens_out: number
}
export interface PursueResult {
  email_id: string
  project_id: string
  project_name: string | null // null for an existing world project (name it from world.json)
  project_created: boolean
  opportunity_id: string
  opportunity_name: string
  stage: string
  previous_stage: string | null
  opportunity_created: boolean
  open: string | null // app route to open next (Hall B's intake)
}
export interface InboxEmail {
  id: string
  from_name: string
  from_addr: string
  from_org: string
  to: string
  subject: string
  received_at: number
  body: string
  attachments: InboxAttachment[]
  project_id: string | null
  live_triage: boolean
  triage: TriageResult | null
  status?: 'new' | 'triaged' | 'pursued' // live API only
  pursue?: PursueResult | null // live API only
}
export interface InboxAppetite {
  asset_types: AssetPack[]
  mw: [number, number]
  regions: { name: string; places: string[] }[]
  min_days_to_bid_due: number
  lead_time_check: boolean
}
export interface InboxSnapshot {
  mailbox: string
  label: string
  notice: string
  as_of: number
  appetite: InboxAppetite
  emails: InboxEmail[] // newest first
}
